//! 管理可反射 UI 的路由、快照及通知；宿主业务动作仍由注册处理器或宿主自己的 typed dispatcher 执行。

#[path = "manager/mod.rs"]
mod manager;

pub use manager::UiEventManager;

use super::route_handler::RouteHandler;
use zircon_runtime_interface::ui::binding::UiEventBinding;
use zircon_runtime_interface::ui::event_ui::UiRouteId;

// handler 为 None 表示路由由宿主 typed dispatcher 执行；并非一个可由本管理器直接执行的空处理器。
#[derive(Clone)]
pub(super) struct RouteEntry {
    pub(super) route_id: UiRouteId,
    pub(super) binding: UiEventBinding,
    pub(super) handler: Option<RouteHandler>,
}

use std::sync::Arc;

use serde_json::Value;

use zircon_runtime_interface::ui::event_ui::{UiInvocationContext, UiInvocationError};

// Arc 让路由表持有宿主注册的可共享处理器；业务状态应通过处理器捕获的 owner 访问，避免复制到反射快照。
pub(super) type RouteHandler =
    Arc<dyn Fn(UiInvocationContext) -> Result<Value, UiInvocationError> + Send + Sync + 'static>;

use crate::core::{CoreResult, ModuleCleanupContext, ModuleLifecycle};

use super::{UiRuntimeDriver, UI_RUNTIME_DRIVER_NAME};

#[derive(Debug, Default)]
pub(super) struct UiModuleLifecycle;

impl ModuleLifecycle for UiModuleLifecycle {
    fn cleanup(&self, context: &ModuleCleanupContext<'_>) -> CoreResult<()> {
        context.with_existing_driver::<UiRuntimeDriver>(UI_RUNTIME_DRIVER_NAME, |driver| {
            driver.close_admission();
            Ok(())
        })?;
        Ok(())
    }
}
